#!/usr/bin/env node
// npm run build:css: compiles src/styles/gateway.css with Tailwind CSS (the classes come from src/components and
// src/pages) into src/assets/gateway-css.ts, the module the Worker serves as /__insulin/gateway.css. The result is
// committed, so neither the deploy nor wrangler needs a CSS step.
//
// npm run check:css (`--check`) writes nothing and fails when the committed module differs from a fresh build; the
// test suite runs the same check.
import { spawn } from 'node:child_process'
import { readFile, writeFile } from 'node:fs/promises'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

export const gatewayDir = resolve(dirname(fileURLToPath(import.meta.url)), '..')
export const CSS_SOURCE = join(gatewayDir, 'src', 'styles', 'gateway.css')
export const CSS_MODULE = join(gatewayDir, 'src', 'assets', 'gateway-css.ts')
const CLI = join(gatewayDir, 'node_modules', '@tailwindcss', 'cli', 'dist', 'index.mjs')

/** The minified stylesheet, from the pinned Tailwind CLI. */
export function compileCss() {
  return new Promise((accept, reject) => {
    const child = spawn(process.execPath, [CLI, '--input', CSS_SOURCE, '--output', '-', '--minify'], {
      cwd: gatewayDir,
      stdio: ['ignore', 'pipe', 'pipe'],
    })
    let css = ''
    let log = ''
    child.stdout.setEncoding('utf8').on('data', (chunk) => { css += chunk })
    child.stderr.setEncoding('utf8').on('data', (chunk) => { log += chunk })
    child.once('error', reject)
    // 'close' rather than 'exit': it waits for stdout and stderr to drain, so the CSS is complete.
    child.on('close', (code) => (code === 0 && css ? accept(css) : reject(new Error(`tailwindcss exited ${code}\n${log}`))))
  })
}

/** The TypeScript module for a compiled stylesheet. */
export function cssModule(css) {
  return [
    '// Generated by `npm run build:css` from src/styles/gateway.css (Tailwind CSS, shadcn/ui theme): do not edit.',
    '// /__insulin/gateway.css, the one stylesheet of every gateway page.',
    `export const GATEWAY_CSS = ${JSON.stringify(css.trim())}`,
    '',
  ].join('\n')
}

/** Whether the committed module matches a fresh build. */
export async function cssIsCurrent() {
  const [expected, committed] = await Promise.all([compileCss().then(cssModule), readFile(CSS_MODULE, 'utf8').catch(() => '')])
  return expected === committed
}

async function main() {
  if (process.argv.includes('--check')) {
    if (await cssIsCurrent()) return
    console.error('src/assets/gateway-css.ts is stale: run `npm run build:css` and commit the result.')
    process.exitCode = 1
    return
  }
  const css = await compileCss()
  await writeFile(CSS_MODULE, cssModule(css))
  console.log(`src/assets/gateway-css.ts: ${Buffer.byteLength(css.trim())} bytes of CSS`)
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) await main()
